function toArray(value) {
  if (value === undefined || value === null) return [];
  if (Array.isArray(value)) {
    return value.map((v) => (v ?? '').toString().trim()).filter(Boolean);
  }
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return [];
    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) {
        return parsed.map((v) => (v ?? '').toString().trim()).filter(Boolean);
      }
    } catch (_) {}
    return trimmed
      .replace(/^[{\[(]/, '')
      .replace(/[}\])]/, '')
      .split(/,|\n|;|\\|\|/)
      .map((part) => part.trim())
      .filter(Boolean);

  }
  if (typeof value === 'object') {
    return Object.values(value)
      .map((v) => (v ?? '').toString().trim())
      .filter(Boolean);
  }
  return [];
}

function stripMarkdown(markdown) {
  if (!markdown) return '';
  let text = markdown.replace(/```[\s\S]*?```/g, ' ');
  text = text.replace(/~{3}[\s\S]*?~{3}/g, ' ');
  text = text.replace(/<script[\s\S]*?<\/script>/gi, ' ');
  text = text.replace(/<style[\s\S]*?<\/style>/gi, ' ');
  text = text.replace(/!\[[^\]]*\]\([^)]+\)/g, ' ');
  text = text.replace(/\[([^\]]*)\]\(([^)]+)\)/g, '$1');
  text = text.replace(/<[^>]+>/g, ' ');
  text = text.replace(/[#*_`>~-]+/g, ' ');
  text = text.replace(/\n/g, ' ');
  return text.replace(/\s+/g, ' ').trim();
}

function unique(values) {
  const seen = new Set();
  const result = [];
  for (const value of values) {
    const current = (value ?? '').toString().trim();
    if (!current) continue;
    const key = current.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(current);
  }
  return result;
}

const requestItems = $items('Webhook Copys DB', 0) || [];
const requestBody = requestItems[0]?.json?.body || {};

const env = (name) => (typeof $env === 'function' ? $env(name) : undefined);
const defaultModel = env('OPENAI_SOCIAL_MODEL') || env('OPENAI_DEFAULT_MODEL') || 'gpt-4o';

function resolvePlatforms(raw) {
  const arr = unique(toArray(raw).map((value) => value.toLowerCase()));
  const supported = ['linkedin', 'facebook'];
  const filtered = arr.filter((value) => supported.includes(value));
  if (filtered.length) return filtered;
  return ['linkedin', 'facebook'];
}

const platforms = resolvePlatforms(requestBody.platforms);
const tone = (requestBody.tone || 'profesional cercano').toString();
const targetAudience = (requestBody.target_audience || 'Profesionales interesados en marketing digital y automatización').toString();
const callToAction = (requestBody.call_to_action || 'Invita a comentar aprendizados y compartir con su red.').toString();
const maxLenLinkedin = Number(requestBody.max_length_linkedin ?? 1300) || 1300;
const maxLenFacebook = Number(requestBody.max_length_facebook ?? 2000) || 2000;
const maxExcerptChars = Number(requestBody.max_excerpt_chars ?? 6000) || 6000;
const openAiModel = (requestBody.openai_model || defaultModel).toString();

return $input.all().map((item, index) => {
  const row = item.json || {};
  const markdown = (row.content_markdown || row.content_html || '').toString();
  const plain = stripMarkdown(markdown);
  const excerpt = plain.length > maxExcerptChars ? plain.slice(0, maxExcerptChars) : plain;
  const summary = plain
    .split(/\. |\n/)
    .map((part) => part.trim())
    .filter(Boolean)
    .slice(0, 4)
    .join('. ');

  const keywords = unique([row.keyword_principal, ...toArray(row.keywords_secundarias)]);
  const tags = unique(toArray(row.tags));

  const base = {
    draft_id: row.draft_id,
    idea_id: row.idea_id,
    keyword_cluster_id: row.keyword_cluster_id,
    idea_title: row.idea_title,
    idea_categoria: row.idea_categoria,
    idea_status: row.idea_status,
    cluster_name: row.cluster_name,
    project_name: row.project_name,
    keyword_principal: row.keyword_principal,
    keywords_secundarias: keywords,
    tags,
    existing_linkedin_copy: row.linkedin_copy || null,
    existing_facebook_copy: row.facebook_copy || null,
    title: row.title || row.meta_title || row.idea_title,
    meta_title: row.meta_title,
    meta_description: row.meta_description,
    word_count: row.word_count || plain.split(/\s+/).filter(Boolean).length,
    article_plain: plain,
    article_excerpt: excerpt,
    article_summary: summary || excerpt.slice(0, 320),
    tone,
    target_audience: targetAudience,
    call_to_action: callToAction,
    platforms,
    max_length_linkedin: maxLenLinkedin,
    max_length_facebook: maxLenFacebook,
    request_body: requestBody,
    openai_model: openAiModel,
    start_time: new Date().toISOString(),
    start_ts_ms: Date.now() + index
  };

  return { json: base };
});

const rawMessage = $json.message?.content || $json.text || $json.response || '';
let cleaned = String(rawMessage).trim();

if (cleaned.startsWith('')) {
  cleaned = cleaned.replace(/^\s*/i, '').replace(/```$/i, '').trim();
} else if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```\s*/i, '').replace(/```$/i, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error('No se pudo parsear la respuesta del modelo a JSON. Respuesta:' + cleaned);
}

const context = $items('Preparar Contexto Copys DB', 0)[$itemIndex]?.json || {};
const platforms = Array.isArray(context.platforms) ? context.platforms : ['linkedin', 'facebook'];

// Intentar obtener una URL del artículo desde el contexto o desde el SELECT original
const articleUrlFallback =
  context.article_url ||
  context.wordpress_post_url ||
  context.post_url ||
  ($items('Seleccionar Drafts Copys', 0)[$itemIndex]?.json?.wordpress_post_url) ||
  null;

function resolvePlatform(data, key) {
  if (!data) return null;
  const direct = data[key];
  if (direct) return direct;
  const alt = data[key.charAt(0).toUpperCase() + key.slice(1)];
  if (alt) return alt;
  if (key === 'linkedin') {
    return data.LinkedIn || data.linked_in || data.linkedin_post || null;
  }
  if (key === 'facebook') {
    return data.Facebook || data.facebook_post || null;
  }
  return null;
}

function buildCopy(block, fallback) {
  if (!block || typeof block !== 'object') {
    return fallback || null;
  }
  const parts = [];
  if (block.hook) parts.push(block.hook.trim());
  if (block.body) parts.push(block.body.trim());
  if (block.cta) parts.push(block.cta.trim());
  if (Array.isArray(block.hashtags) && block.hashtags.length) {
    const tags = block.hashtags.map((tag) => (tag || '').toString().trim()).filter(Boolean);
    if (tags.length) parts.push(tags.join(' '));
  }
  return parts.filter(Boolean).join(' ') || fallback || null; // <-- con espacio
}

const linkedinStruct = resolvePlatform(parsed, 'linkedin');
const facebookStruct = resolvePlatform(parsed, 'facebook');

const linkedinCopy = platforms.includes('linkedin')
  ? buildCopy(linkedinStruct, context.existing_linkedin_copy)
  : context.existing_linkedin_copy || null;

const facebookCopy = platforms.includes('facebook')
  ? buildCopy(facebookStruct, context.existing_facebook_copy)
  : context.existing_facebook_copy || null;

// Enlaces individuales por plataforma (si el modelo no los da, usamos el fallback)
const linkedinLink = (linkedinStruct && linkedinStruct.link) || articleUrlFallback;
const facebookLink = (facebookStruct && facebookStruct.link) || articleUrlFallback;

const usage = $json.usage || $json.data?.[0]?.usage || {};
const totalTokens = usage.total_tokens ?? usage.totalTokens ?? null;

return [{
  json: {
    ...context,
    structured_copies: parsed,
    linkedin_copy_new: linkedinCopy,
    facebook_copy_new: facebookCopy,
    linkedin_link: linkedinLink || null,
    facebook_link: facebookLink || null,
    llm_tokens_used: totalTokens
  }
}];

const idx = $itemIndex;
const context = $items('Parsear Copys DB', 0)[idx]?.json || {};
const updated = $json || {};

return [{
  json: {
    ...context,
    updated_draft: updated,
    linkedin_copy_result: updated.linkedin_copy || context.linkedin_copy_new || context.existing_linkedin_copy || null,
    facebook_copy_result: updated.facebook_copy || context.facebook_copy_new || context.existing_facebook_copy || null
  }
}];

const context = $json || {};
const endTime = new Date();
const durationMs = Math.max(0, Date.now() - (context.start_ts_ms || Date.now()));

const jobLog = {
  job_name: 'SEO - 15 Copys Redes DB',
  job_type: 'social_copy',
  status: 'success',
  related_keyword_id: context.keyword_cluster_id || null,
  related_idea_id: context.idea_id || null,
  related_draft_id: context.draft_id || null,
  started_at: context.start_time || endTime.toISOString(),
  completed_at: endTime.toISOString(),
  duration_ms: durationMs,
  input_data: {
    platforms: context.platforms || [],
    tone: context.tone || null,
    target_audience: context.target_audience || null,
    call_to_action: context.call_to_action || null
  },
  output_data: {
    linkedin_copy: context.linkedin_copy_result || null,
    facebook_copy: context.facebook_copy_result || null,
    structured_copies: context.structured_copies || {},
    tokens_used: context.llm_tokens_used || null
  }
};

return [{ json: { ...context, job_log: jobLog } }];

